app.json:
{
  "agent": {
    "name": "account-desk",
    "file": "agent.md"
  },
  "budget": {
    "per_run": 0.10
  },
  "capabilities": {
    "records": {
      "company": "r",
      "contact": "r",
      "deal": "rw",
      "note": "rw"
    },
    "connectors": {
      "gmail": {
        "as": "me",
        "can": [
          "read",
          "search"
        ]
      },
      "calendar": {
        "as": "me",
        "can": [
          "list"
        ]
      }
    },
    "ai": [
      "summarise"
    ]
  },
  "commands": [
    {
      "id": "draft-follow-up",
      "label": "Draft follow-up",
      "for": "deal",
      "run": "draft-follow-up",
      "params": {
        "deal": "$record.id"
      }
    },
    {
      "id": "explain-risk",
      "label": "Explain risk",
      "for": "deal",
      "run": "explain-risk",
      "params": {
        "deal": "$record.id"
      }
    },
    {
      "id": "update-stage",
      "label": "Propose stage or next step",
      "for": "deal",
      "run": "update-stage",
      "params": {
        "deal": "$record.id"
      }
    }
  ],
  "id": "01M8DDCARR54ZW0AZJ06BY42VV",
  "kit": 2,
  "name": "Account desk",
  "records": {
    "company": {
      "common": "organization",
      "title": "name",
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "website": {
          "type": "url"
        }
      }
    },
    "contact": {
      "common": "person",
      "title": "name",
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "email": {
          "type": "email"
        },
        "phone": {
          "type": "phone"
        },
        "organization": {
          "type": "ref",
          "to": "company"
        }
      }
    },
    "deal": {
      "title": "name",
      "fields": {
        "name": {
          "type": "text",
          "required": true,
          "unique": true
        },
        "company": {
          "type": "ref",
          "to": "company"
        },
        "contact": {
          "type": "ref",
          "to": "contact"
        },
        "stage": {
          "type": "enum",
          "values": [
            "Lead",
            "Qualified",
            "Proposal",
            "Won",
            "Lost"
          ],
          "required": true,
          "default": "Lead"
        },
        "value": {
          "type": "money",
          "currency": "USD"
        },
        "close_date": {
          "type": "date"
        },
        "next_step": {
          "type": "text"
        },
        "risk": {
          "type": "longtext"
        }
      }
    },
    "note": {
      "title": "title",
      "fields": {
        "title": {
          "type": "text",
          "required": true
        },
        "deal": {
          "type": "ref",
          "to": "deal"
        },
        "contact": {
          "type": "ref",
          "to": "contact"
        },
        "kind": {
          "type": "enum",
          "values": [
            "Follow-up",
            "Meeting brief",
            "Risk note"
          ],
          "required": true,
          "default": "Follow-up"
        },
        "body": {
          "type": "longtext"
        },
        "source": {
          "type": "text"
        }
      }
    }
  },
  "triggers": [
    {
      "id": "desk-daily",
      "on": "schedule",
      "cron": "0 7 * * 1-5",
      "run": "desk-brief"
    },
    {
      "id": "meeting-soon",
      "on": "schedule",
      "cron": "*/5 * * * *",
      "run": "meeting-brief"
    }
  ],
  "version": 1
}
